import { useEffect, useMemo, useRef, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import {
  addMonths,
  eachDayOfInterval,
  endOfMonth,
  endOfWeek,
  format,
  isSameMonth,
  isToday,
  parseISO,
  startOfMonth,
  startOfWeek,
} from 'date-fns'
import { id as idLocale } from 'date-fns/locale'
import { Icon, type IconName } from '@/design-system/Icon'
import { Card, EmptyState, Field, PARTNER_VISIBILITY_OPTIONS, Sheet, VisibilityBadge } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, softDelete } from '@/db/db'
import { useHolidays, type Holiday } from './holidays'
import { occurrencesInRange } from './recurrence'
import CalendarPlanner, { type PlannerView } from './Index'
import type { CalendarEvent, EventType, Recurrence, Visibility } from '@/types/domain'
import './calendar.css'
import { useT } from '@/i18n'

const TYPE_UI: Record<EventType, { icon: IconName; tone: string }> = {
  date: { icon: 'date', tone: 'primary' },
  task: { icon: 'tasks', tone: 'mint' },
  bill: { icon: 'money', tone: 'yellow' },
  family: { icon: 'family', tone: 'lavender' },
  me_time: { icon: 'self', tone: 'blue' },
  health: { icon: 'health', tone: 'mint' },
  celebration: { icon: 'memories', tone: 'yellow' },
  private: { icon: 'private', tone: '' },
}

const DOW = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']

/** Month stays first: it is the view people arrive expecting. */
const VIEWS = ['bulan', 'berdua', 'minggu', 'agenda', 'usulan', 'pengingat'] as const

/**
 * Kalender bareng (CAL-01..04).
 *
 * The month grid is a 7-column CSS grid that shrinks its cells instead of
 * scrolling sideways; below ~430 px the grid becomes dot-only and the agenda
 * below it carries the detail. Nothing here ever overflows horizontally.
 */
export default function Calendar() {
  const t = useT()
  const { profile } = useSession()
  const me = profile?.id
  const [params, setParams] = useSearchParams()
  const [cursor, setCursor] = useState(() => new Date())
  const [selected, setSelected] = useState(() => format(new Date(), 'yyyy-MM-dd'))
  const [sheetOpen, setSheetOpen] = useState(params.get('baru') === '1')
  // The month grid stays the default view — it is the one people already know,
  // and every other view is a tab away rather than a replacement.
  const [view, setView] = useState<'bulan' | PlannerView>('bulan')
  const gridRef = useRef<HTMLDivElement>(null)

  const events = useOwned<CalendarEvent>('events', me)
  const holidays = useHolidays(cursor.getFullYear())

  /**
   * Occurrences for the visible window, recurrences expanded on the fly.
   * A repeat is never stored as its own row (see recurrence.ts).
   */
  const byDate = useMemo(() => {
    const from = format(startOfWeek(startOfMonth(cursor), { weekStartsOn: 1 }), 'yyyy-MM-dd')
    const to = format(endOfWeek(endOfMonth(cursor), { weekStartsOn: 1 }), 'yyyy-MM-dd')
    return occurrencesInRange(events ?? [], from, to)
  }, [events, cursor])

  /**
   * Chunked into weeks, not a flat list: `role="grid"` requires `role="row"`
   * between the grid and its cells, and a screen reader announces "row 3,
   * column 5" off the back of it. axe caught the flat version.
   */
  const weeks = useMemo(() => {
    const start = startOfWeek(startOfMonth(cursor), { weekStartsOn: 1 })
    const end = endOfWeek(endOfMonth(cursor), { weekStartsOn: 1 })
    const days = eachDayOfInterval({ start, end })
    return Array.from({ length: Math.ceil(days.length / 7) }, (_, i) => days.slice(i * 7, i * 7 + 7))
  }, [cursor])

  if (!profile || !me) return null

  const selectedEvents = (byDate.get(selected) ?? []).sort((a, b) =>
    (a.event.time ?? '').localeCompare(b.event.time ?? ''),
  )
  const selectedHolidays = holidays.filter((h) => h.date === selected)

  /** Arrow keys move by day/week, like a native date grid. */
  function onKeyDown(e: React.KeyboardEvent) {
    const delta = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key]
    if (delta === undefined) return
    e.preventDefault()
    const next = new Date(parseISO(selected))
    next.setDate(next.getDate() + delta)
    const iso = format(next, 'yyyy-MM-dd')
    setSelected(iso)
    if (!isSameMonth(next, cursor)) setCursor(next)
    requestAnimationFrame(() => {
      gridRef.current?.querySelector<HTMLElement>(`[data-date="${iso}"]`)?.focus()
    })
  }

  return (
    <div className="stack">
      <div className="row row--between">
        <h1>{t('nav.calendar')}</h1>
        <button
          className="btn btn--sm"
          onClick={() => {
            setSheetOpen(true)
          }}
        >
          <Icon name="plus" size={16} /> {t('quick.event')}
        </button>
      </div>

      <div className="segmented cal2__tabs" role="group" aria-label={t('calendar2.viewGroup')}>
        {VIEWS.map((v) => (
          <button key={v} type="button" aria-pressed={view === v} onClick={() => setView(v)}>
            {t(`calendar2.view.${v}` as const)}
          </button>
        ))}
      </div>

      {view !== 'bulan' && <CalendarPlanner view={view} date={selected} onDate={setSelected} />}

      {view === 'bulan' && (
        <>
      <Card>
        <div className="row row--between">
          <button className="btn btn--ghost btn--sm btn--icon" onClick={() => setCursor(addMonths(cursor, -1))}>
            <Icon name="chevron-left" size={18} label={t('cal.prevMonth')} />
          </button>
          <strong aria-live="polite">{format(cursor, 'MMMM yyyy', { locale: idLocale })}</strong>
          <button className="btn btn--ghost btn--sm btn--icon" onClick={() => setCursor(addMonths(cursor, 1))}>
            <Icon name="chevron-right" size={18} label={t('cal.nextMonth')} />
          </button>
        </div>

        <div className="cal" role="grid" aria-label={t('cal.monthGrid')} ref={gridRef} onKeyDown={onKeyDown}>
          <div className="cal__row cal__row--head" role="row">
            {DOW.map((d) => (
              <span key={d} role="columnheader" className="cal__dow">
                {d}
              </span>
            ))}
          </div>
          <div className="cal__body" role="rowgroup">
            {weeks.map((week) => (
              <div className="cal__row" role="row" key={format(week[0]!, 'yyyy-MM-dd')}>
                {week.map((d) => {
                  const iso = format(d, 'yyyy-MM-dd')
                  const dayEvents = byDate.get(iso) ?? []
                  const dayHolidays = holidays.filter((h) => h.date === iso)
                  const outside = !isSameMonth(d, cursor)
                  return (
                    <div role="gridcell" key={iso} className="cal__gridcell">
                      <button
                        type="button"
                        data-date={iso}
                        className="cal__cell"
                        data-outside={outside}
                        data-today={isToday(d)}
                        aria-pressed={selected === iso}
                        tabIndex={selected === iso ? 0 : -1}
                        aria-label={`${format(d, 'EEEE d MMMM yyyy', { locale: idLocale })}${
                          dayEvents.length ? `, ${t('cal.eventCount', { n: dayEvents.length })}` : ''
                        }${dayHolidays.length ? `, ${dayHolidays[0]!.name}` : ''}`}
                        onClick={() => setSelected(iso)}
                      >
                        <span className="cal__num" data-holiday={dayHolidays.some((h) => h.official)}>
                          {format(d, 'd')}
                        </span>
                        <span className="cal__dots" aria-hidden="true">
                          {dayEvents.slice(0, 3).map((o) => (
                            <i key={o.event.id} data-tone={TYPE_UI[o.event.type].tone} />
                          ))}
                          {dayHolidays.length > 0 && <i data-tone="holiday" />}
                        </span>
                      </button>
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
        </div>

        <p className="card__hint" style={{ marginTop: 'var(--space-2)' }}>
          {t('cal.arrowHint')}
        </p>
      </Card>

      <Card
        title={format(parseISO(selected), 'EEEE, d MMMM yyyy', { locale: idLocale })}
        icon="calendar"
        action={
          <button className="btn btn--sm" onClick={() => setSheetOpen(true)}>
            <Icon name="plus" size={16} /> {t('common.add')}
          </button>
        }
      >
        {selectedHolidays.map((h) => (
          <div key={h.name} className={`banner ${h.official ? '' : 'banner--warn'}`}>
            <Icon name={h.official ? 'calendar' : 'memories'} size={18} />
            <span>
              <strong>{h.name}</strong>
              <br />
              {h.official ? t('cal.officialHoliday', { source: h.source }) : t('cal.optionalMoment')}
            </span>
          </div>
        ))}

        {selectedEvents.length === 0 ? (
          <EmptyState icon="calendar" title={t('today.noUpcoming')} hint={t('today.noUpcomingHint')} />
        ) : (
          <ul className="list">
            {selectedEvents.map((o) => (
              <li key={`${o.event.id}-${o.date}`} className="list__item">
                <Icon name={TYPE_UI[o.event.type].icon} size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{o.event.title}</strong>
                  <span className="card__hint">
                    {o.event.time ? `${o.event.time} · ` : ''}
                    {t(`type.${o.event.type}` as const)}
                    {o.event.recurrence
                      ? ` · ${t('cal.repeatBadge', {
                          freq: t(`cal.repeat.${o.event.recurrence.freq}` as const).toLowerCase(),
                        })}`
                      : ''}
                  </span>
                </span>
                <VisibilityBadge visibility={o.event.visibility} />
                <button
                  className="btn btn--ghost btn--sm btn--icon"
                  onClick={() => softDelete('events', o.event.id, me)}
                >
                  <Icon name="close" size={16} label={t('common.deleteX', { name: o.event.title })} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </Card>
        </>
      )}

      <NewEventSheet
        open={sheetOpen}
        date={selected}
        me={me}
        onClose={() => {
          setSheetOpen(false)
          if (!params.has('baru')) return
          params.delete('baru')
          setParams(params, { replace: true })
        }}
      />
    </div>
  )
}

function NewEventSheet({
  open,
  date,
  me,
  onClose,
}: {
  open: boolean
  date: string
  me: string
  onClose: () => void
}) {
  const t = useT()
  const [title, setTitle] = useState('')
  const [when, setWhen] = useState(date)
  const [time, setTime] = useState('')
  const [type, setType] = useState<EventType>('date')
  const [visibility, setVis] = useState<Visibility>('shared')
  const [maskedTitle, setMasked] = useState('')
  const [repeat, setRepeat] = useState<Recurrence['freq'] | 'none'>('none')
  const [until, setUntil] = useState('')

  useEffect(() => setWhen(date), [date])

  async function save() {
    if (!title.trim()) return
    await db.events.add({
      ...newEnvelope(me, visibility === 'private' ? 'C1_personal' : 'C2_shared_ops', { visibility }),
      kind: 'event',
      title: title.trim(),
      date: when,
      ...(time ? { time } : {}),
      type,
      ...(visibility === 'private' ? { maskedTitle: maskedTitle.trim() || 'Waktu pribadi' } : {}),
    } as never)
    setTitle('')
    setTime('')
    setMasked('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('cal.newEvent')}>
      <div className="stack">
        <Field label={t('cal.whatToNote')}>
          {(p) => (
            <input {...p} type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder={t('cal.eventPlaceholder')} />
          )}
        </Field>
        <div className="row" style={{ gap: 'var(--space-3)', alignItems: 'flex-end' }}>
          <div className="grow">
            <Field label={t('common.date')}>
              {(p) => <input {...p} type="date" value={when} onChange={(e) => setWhen(e.target.value)} />}
            </Field>
          </div>
          <div className="grow">
            <Field label={t('common.time')} hint={t('common.optional')}>
              {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
            </Field>
          </div>
        </div>

        <Field label={t('cal.kind')}>
          {(p) => (
            <select {...p} value={type} onChange={(e) => setType(e.target.value as EventType)}>
              {(Object.keys(TYPE_UI) as EventType[]).map((ty) => (
                <option key={ty} value={ty}>
                  {t(`type.${ty}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>

        <Field label={t('cal.repeat')}>
          {(p) => (
            <select
              {...p}
              value={repeat}
              onChange={(e) => setRepeat(e.target.value as Recurrence['freq'] | 'none')}
            >
              <option value="none">{t('cal.repeat.none')}</option>
              <option value="daily">{t('cal.repeat.daily')}</option>
              <option value="weekly">{t('cal.repeat.weekly')}</option>
              <option value="monthly">{t('cal.repeat.monthly')}</option>
              <option value="yearly">{t('cal.repeat.yearly')}</option>
            </select>
          )}
        </Field>

        {repeat !== 'none' && (
          <Field label={t('cal.repeatUntil')} hint={t('common.optional')}>
            {(p) => <input {...p} type="date" value={until} onChange={(e) => setUntil(e.target.value)} />}
          </Field>
        )}

        <Field label={t('common.whoCanSee')}>
          {(p) => (
            <select {...p} value={visibility} onChange={(e) => setVis(e.target.value as Visibility)}>
              {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                <option key={v} value={v}>
                  {t(`vis.opt.${v}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>

        {visibility === 'private' && (
          <Field
            label={t('cal.maskedAs')}
            hint={t('cal.maskedHint')}
          >
            {(p) => (
              <input {...p} type="text" value={maskedTitle} placeholder={t('cal.maskedDefault')} onChange={(e) => setMasked(e.target.value)} />
            )}
          </Field>
        )}

        <button className="btn btn--block" onClick={save} disabled={!title.trim()}>
          {t('cal.saveEvent')}
        </button>
      </div>
    </Sheet>
  )
}

export type { Holiday }
